pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 lockTime, uint256 putAmount, uint256 collectAmount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(putAmount > 0);
        vm.assume(collectAmount > 0);
        vm.assume(collectAmount <= putAmount);

        // Need to set LogFile before initialization, but LogFile is not pre-deployed.
        // Deploy a dummy helper that implements Log interface (just for success) to bypass revert.
        // Actually LogFile must be set before Initialized(). The reference contract just needs any address
        // that has the AddMessage function with the right signature. We deploy a minimal helper.
        address logAddress = address(new LogHelper());

        c.SetLogFile(logAddress);
        c.SetMinSum(minSum);
        c.Initialized();

        // Now minSum is locked in reference; mutant sets it to 0
        // To trigger Collect, we need acc.balance >= MinSum && acc.balance >= _am && block.timestamp > acc.unlockTime
        // Put some funds and wait past unlockTime
        vm.deal(actor, putAmount);
        vm.prank(actor);
        c.Put{value: putAmount}(lockTime);

        // Warp past unlockTime
        vm.warp(block.timestamp + lockTime + 1);

        // Collect expects msg.sender to be payable, so use actor
        vm.prank(actor);
        c.Collect(collectAmount);

        // After Collect, MinSum should be minSum if reference, but 0 if mutant
        uint256 actualMinSum = c.MinSum();
        // Reference invariant: MinSum == minSum (the value set before initialization)
        assertTrue(actualMinSum == minSum);
    }
}

contract LogHelper {
    // Minimal implementation of Log.AddMessage to prevent revert inside Put/Collect
    function AddMessage(address, uint256, string memory) public {}
}

