pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 lockTime, uint256 collectAmount) public {
        // 1. Bound parameters to admissible domain. minSum must be > 0 for a meaningful threshold,
        // collectAmount must be < minSum to see the difference.
        vm.assume(minSum > 0);
        vm.assume(collectAmount < minSum);
        vm.assume(minSum <= type(uint256).max / 2);
        vm.assume(collectAmount < minSum);
        vm.assume(lockTime <= type(uint256).max - block.timestamp);
        // 2. Setup: Initialize, then set MinSum to the fuzzed value.
        c.Initialized();
        c.SetMinSum(minSum);
        // Ensure the sender has enough balance to pass the balance check in Collect.
        // We must also put funds into the contract for the sender.
        // Use a fresh address as sender.
        address sender = address(uint160(uint256(keccak256(abi.encodePacked(block.timestamp, minSum, lockTime, collectAmount)))));
        vm.deal(sender, minSum);
        vm.prank(sender);
        c.Put{value: minSum}(lockTime);
        // Warp past unlock time so Collect is allowed based on time.
        vm.warp(block.timestamp + lockTime + 1);
        // 3. Attempt Collection of an amount less than MinSum.
        bool ok;
        vm.prank(sender);
        try c.Collect(collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }
        // 4. The rule: Since minSum > collectAmount, Collect should fail in the reference.
        // In the mutant, MinSum is 0 so Collect succeeds (or at least doesn't revert for the MinSum check).
        // We assert that in the reference, the call fails. This fails in the mutant because it allows the collect.
        assertTrue(!ok, "Reference: Collect should revert when amount < MinSum");
    }
}

