pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _min, uint256 _lockTime, uint256 _collectAmt, uint256 _seed) public {
        // bound to plausible values
        _min = bound(_min, 1, type(uint128).max);
        _lockTime = bound(_lockTime, 0, 365 days);
        _collectAmt = bound(_collectAmt, 1, _min);

        // set up MinSum before initialization
        c.SetMinSum(_min);
        c.Initialized();

        // attempt to change MinSum after initialization (must revert)
        bool postInitSetOk;
        try c.SetMinSum(_seed) { postInitSetOk = true; } catch { postInitSetOk = false; }

        // fund an account and Put
        address usr = address(uint160(_seed + 1));
        vm.deal(usr, _min);
        vm.prank(usr);
        c.Put{value: _min}(_lockTime);

        // warp past unlock time
        vm.warp(block.timestamp + _lockTime + 1);

        // Collect
        vm.prank(usr);
        c.Collect(_collectAmt);

        // invariants: if postInitSetOk is true, MinSum could have been altered (bug)
        // If postInitSetOk is false, MinSum must remain _min
        // The reference always reverts post-init SetMinSum, so postInitSetOk == false and MinSum == _min
        // The mutant does not revert, postInitSetOk can be true, then MinSum may be zero
        assertTrue(!postInitSetOk || c.MinSum() == _min);
    }
}

