pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint112 value, uint128 minSumArg, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(minSumArg > 0);
        vm.assume(value > 0);

        // 1. Set up: deploy adversarial callee that always reverts on Collect call
        Reverter reverter = new Reverter();
        c.Initialized();
        c.SetLogFile(address(reverter));

        // 2. Precondition: ensure contract is not initialized before SetMinSum
        //    (we re-create or use a fresh contract? Actually the contract is already initialized above.
        //     To test the SetMinSum behavior when UNINITIALIZED, we need a fresh contract.
        //     So we deploy a new one.)
        c = new C(); // fresh contract, intitalized = false
        c.SetLogFile(address(reverter));

        // 3. Actor deposits some Ether to have balance for Collect
        vm.deal(actor, value);
        vm.prank(actor);
        c.Put{value: value}(0);

        // 4. Now call SetMinSum with fuzzed argument
        vm.prank(actor);
        c.SetMinSum(minSumArg);

        // 5. Warp past unlock time to allow Collect
        vm.warp(block.timestamp + 1);

        // 6. Attempt Collect with amount exactly equal to MinSum (as set)
        //    On reference: if MinSum == minSumArg (>0) and balance >= minSumArg, Collect should succeed if balance >= MinSum.
        //    Actually we need the adversarial reverter to make the low-level call from Collect fail,
        //    so Collect reverts in BOTH reference and bug if we try to withdraw? Wait, we need to distinguish.
        //    The reverter is used to make the external call in Collect ALWAYS revert, so Collect itself reverts.
        //    That doesn't help distinguish MinSum values.
        //    Let's instead observe the revert/success of Collect based on MinSum threshold.
        //    We remove the reverter and use a normal address.
        //    Recreate without reverter.
        delete reverter;
    }
}

